}, "warranty": {"de": "Herstellergarantie noch nicht geprüft. Beim Kauf von einem Händler in der EU bzw. UK gelten die gesetzlichen Gewährleistungsrechte.", "en": "Manufacturer warranty terms not yet verified. Statutory consumer rights apply when buying from a UK or EU seller."}, "airGapped": "no", "platforms": ["windows", "macos", "linux", "android"], "priceNote": {"de": "Unverbindliche Preisempfehlung laut Drittquellen zum angegebenen Datum; die Quellen widersprachen sich teils. Bitte im offiziellen Shop prüfen.", "en": "Recommended retail price as listed by third-party sources on the date shown; sources disagreed. Confirm at the official store."}, "advisories": [], "factStatus": {"price": "unverified", "assets": "manufacturer_claim", "backup": "manufacturer_claim", "multisig": "manufacturer_claim", "warranty": "unverified", "airGapped": "manufacturer_claim", "platforms": "manufacturer_claim", "openSource": "manufacturer_claim", "passphrase": "manufacturer_claim", "connectivity": "manufacturer_claim", "secureElement": "manufacturer_claim"}, "formFactor": "stick", "openSource": {"note": {"de": "Firmware und Hardware-Designdateien sind auf GitHub veröffentlicht.", "en": "Firmware and hardware design files are published on GitHub."}, "firmware": "yes", "hardware": "yes"}, "passphrase": true, "bitcoinOnly": false, "officialUrl": "https://bitbox.swiss/bitbox02/", "releaseYear": 2019, "assetBreadth": 2, "connectivity": ["usb", "microsd"], "discontinued": false, "assetsSummary": {"de": "Multi-Edition: Bitcoin plus eine kuratierte Auswahl weiterer Assets (z. B. Ethereum und ERC-20-Token, Litecoin). Bitcoin-only-Edition: nur BTC.", "en": "Multi edition: Bitcoin plus a curated set of other assets (e.g. Ethereum and ERC-20 tokens, Litecoin). Bitcoin-only edition: BTC only."}, "companionApps": "BitBoxApp; compatible with Sparrow, Electrum, Specter and others", "secureElement": {"chip": "Microchip ATECC608 (dual-chip design with general-purpose MCU)", "present": true, "certification": ""}, "priceCheckedAt": "2026-10-13", "scoreRationale": {"de": "Starkes Open-Source-Sicherheitsmodell und sehr gute Backup-Optionen; Funktionen durch reine USB-Anbindung begrenzt.", "en": "Strong open-source security model and excellent backup options; features limited by USB-only connectivity."}, "usabilityNotes": {"de": "Wird direkt per USB-C angeschlossen; die Einrichtung führt die BitBoxApp.", "en": "Plugs directly into a USB-C port; setup is guided by the BitBoxApp."}, "btcOnlyFirmware": true, "securityArchitecture": {"de": "Zwei-Chip-Design: Ein Allzweck-Mikrocontroller führt die quelloffene Firmware aus, ein Sicherheitschip schützt Geheimnisse vor physischem Auslesen und begrenzt PIN-Versuche. Eine Bitcoin-only-Firmware reduziert den Code auf dem Gerät. Backups lassen sich zusätzlich zur 24-Wörter-Phrase auf microSD speichern.", "en": "A dual-chip design: a general-purpose microcontroller runs the open-source firmware, while a secure chip protects secrets against physical extraction and enforces PIN attempt limits. Bitcoin-only firmware is available, reducing the code that runs on the device. Backups can be written to microSD in addition to (or instead of) the standard 24-word recovery phrase."}}', NULL, '2026-10-13 21:58:13.890924+00', '2026-10-13 22:19:58.752787+00');
