rt."}, "usabilityNotes": {"de": "", "en": ""}, "btcOnlyFirmware": true, "securityArchitecture": {"de": "Behält den Open-Source-Ansatz der BitBox02 bei und ergänzt einen eigenen Bluetooth-LE-Chip (Renesas SmartBond DA14531) für iPhone und iPad. Geheimnisse schützt laut Datenblatt ein Infineon OPTIGA Trust M V3.", "en": "Keeps the BitBox02''s open-source firmware approach and adds a dedicated Bluetooth Low Energy chip (Renesas SmartBond DA14531) so the device can pair with iPhone and iPad. Secrets are protected by an Infineon OPTIGA Trust M V3 secure chip, according to the manufacturer''s datasheet."}}', NULL, '2026-10-13 21:58:13.89652+00', '2026-10-13 22:19:58.796001+00');
INSERT INTO public.products VALUES ('ledger-nano-s-plus', 'ledger', 'Ledger Nano S Plus', 'review', '{"cons": {"de": ["Closed-Source-Betriebssystem", "Kein Bluetooth, kein iPhone", "Kleines Display, Tastenbedienung", "Vergangene Kundendaten-Lecks"], "en": ["Closed-source secure-element OS", "No Bluetooth, no iPhone support", "Small screen, button navigation", "History of customer-data leaks"]}, "pros": {"de": ["Sehr günstig", "Riesige Asset-Auswahl", "Zertifiziertes Secure Element", "Ausgereifte App"], "en": ["Very low price", "Huge asset support", "Certified secure element", "Polished app"]}, "image": null, "input": "Two buttons", "backup": ["bip39", "cloud_optional"], "prices": {"EUR": null, "GBP": null, "USD": 79}, "scores": {"value": 8.5, "backup": 7, "privacy": 5, "features": 8.5, "security": 7.5, "usability": 8}, "avoidIf": {"de": "Sie Open-Source- oder Bitcoin-only-Firmware voraussetzen.", "en": "You require open-source firmware or Bitcoin-only firmware."}, "battery": false, "bestFor": {"de": "Preisbewusste Multi-Asset-Nutzer auf Desktop oder Android.", "en": "Budget-conscious multi-asset holders on desktop or Android."}, "display": "Monochrome OLED", "sources": [{"url": "https://www.ledger.com/", "label": "Ledger — official site"}], "tagline": {"de": "Ledgers Einstiegsmodell mit USB-C und sehr breiter Asset-Unterstützung", "en": "Ledger''s entry-level USB-C wallet with very broad asset support"}, "editions": [], "multisig": "basic", "shipping": {"DE": {"de": "Noch nicht geprüft – Lieferzeit und Einfuhrabgaben im Checkout prüfen.", "en": "Not yet verified — check delivery times and import charges at checkout."}, "GB": {"de": "Noch nicht geprüft – Lieferzeit, MwSt. und Einfuhrabgaben im Checkout prüfen.", "en": "Not yet verified — check delivery times, VAT and import charges at checkout."}}, "warranty": {"de": "Herstellergarantie noch nicht geprüft. Beim Kauf von einem Händler in der EU bzw. UK gelten die gesetzlichen Gewährleistungsrechte.", "en": "Manufacturer warranty terms not yet verified. Statutory consumer rights apply when buying from a UK or EU seller."}, "airGapped": "no", "platforms": ["windows", "macos", "linux", "android"], "priceNote": {"de": "Unverbindliche Preisempfehlung laut Drittquellen zum angegebenen Datum; die Quellen widersprachen sich teils. Bitte im offiziellen Shop prüfen.", "en": "Recommended retail price as listed by third-party sources on the date shown; sources disagreed. Confirm at the official store."}, "advisories": [{"url": "", "date": "2020-07-14", "title": {"de": "Datenleck der Kundendatenbank (Onlineshop)", "en": "Customer database breach (e-commerce)"}, "summary": {"de": "Ledger meldete, dass Kontaktdaten aus der Shop- und Marketing-Datenbank abgeflossen sind. Gerätschlüssel waren nicht betroffen, doch Betroffene wurden mit Phishing und Drohungen angeschrieben. Seien Sie bei Nachrichten im Namen von Ledger misstrauisch.", "en": "Ledger disclosed that customer contact data from its e-commerce and marketing database was exposed. Device keys were not affected, but affected customers were targeted by phishing and threats. Be suspicious of any message claiming to be from Ledger."}, "severity": "warning"}, {"url": "", "date": "2023-05-16", "title": {"de": "Ankündigung von Ledger Recover", "en": "Ledger Recover announcement"}, "summary": {"de": "Ledger kündigte Recover an, einen optionalen kostenpflichtigen Dienst, der verschlüsselte Teile des Seeds bei Dritten sichert. Er ist freiwillig, zeigte aber, dass die geschlossene Firmware Schlüsselmaterial mit Zustimmung exportieren kann – was eine Debatte über Vertrauen in Closed-Source-Firmware auslöste.", "en": "Ledger announced Recover, an optional paid service that backs up encrypted shares of the seed with third parties. It is opt-in, but it showed that the closed firmware can export key material when the user consents, which prompted debate about trust in closed-source firmware."}, "severity": "info"}, {"url": "", "date": "2023-12-14", "title": {"de": "Supply-Chain-Angriff auf Ledger Connect Kit", "en": "Ledger Connect Kit supply-chain attack"}, "summary": {"de": "Eine kompromittierte Version der JavaScript-Bibliothek Connect Kit wurde veröffentlicht und genutzt, um Nutzer betroffener Web-Apps zu bestehlen. Die Geräte selbst waren nicht kompromittiert. Prüfen Sie Transaktionsdetails stets auf dem Gerätedisplay.", "en": "A compromised version of Ledger''s Connect Kit JavaScript library was published and used to drain users of affected third-party web apps. The hardware devices themselves were not compromised. Always verify transaction details on the device screen."}, "severity": "warning"}], "factStatus": {"price": "unverified", "assets": "manufacturer_claim", "backup": "manufacturer_claim", "multisig": "manufacturer_claim", "warranty": "unverified", "airGapped": "manufacturer_claim", "platforms": "manufacturer_claim", "openSource": "manufacturer_claim", "passphrase": "manufacturer_claim", "connectivity": "manufacturer_claim", "secureElement": "manufacturer_claim"}, "formFactor": "stick", "openSource": {"note": {"de": "Apps sind Open Source; das Betriebssystem im Secure Element ist geschlossen.", "en": "Apps are open source; the secure-element operating system is closed."}, "firmware": "partial", "hardware": "no"}, "passphrase": true, "bitcoinOnly": false, "officialUrl": "https://www.ledger.com/", "releaseYear": 2022, "assetBreadth": 5, "connectivity": ["usb"], "discontinued": false, "assetsSummary": {"de": "Tausende Coins und Token über Ledger Wallet (früher Ledger Live) und Drittanbieter-Wallets.", "en": "Thousands of coins and tokens via Ledger Wallet (formerly Ledger Live) and third-party wallets."}, "companionApps": "Ledger Wallet (formerly Ledger Live); MetaMask, Sparrow, Electrum and others", "secureElement": {"chip": "ST33K1M5", "present": true, "certification": "CC EAL6+ (chip)"}, "priceCheckedAt": "2026-10-13", "scoreRationale": {"de": "Sehr gutes Preis-Leistungs-Verhältnis; Transparenz durch geschlossene Firmware und Datenlecks eingeschränkt.", "en": "Excellent value and asset support; privacy and transparency held back by closed firmware and past data leaks."}, "usabilityNotes": {"de": "", "en": ""}, "btcOnlyFirmware": false, "securityArchitecture": {"de": "Schlüssel liegen in einem zertifizierten Secure Element mit Ledgers proprietärem Betriebssystem (BOLOS). Das bietet starken Schutz gegen physische Angriffe, ist aber öffentlich nicht prüfbar. Optional gibt es den kostenpflichtigen Cloud-Dienst Ledger Recover.", "en": "Keys live inside a certified secure element running Ledger''s proprietary OS (BOLOS). This gives strong resistance to physical attacks, but the OS cannot be independently audited by the public. Ledger Recover, an optional paid cloud recovery service, is available."}}', NULL, '2026-10-13 21:58:13.900438+00', '2026-10-13 22:19:58.799313+00');
