ry": {"de": "Eine kompromittierte Version der JavaScript-Bibliothek Connect Kit wurde veröffentlicht und genutzt, um Nutzer betroffener Web-Apps zu bestehlen. Die Geräte selbst waren nicht kompromittiert. Prüfen Sie Transaktionsdetails stets auf dem Gerätedisplay.", "en": "A compromised version of Ledger''s Connect Kit JavaScript library was published and used to drain users of affected third-party web apps. The hardware devices themselves were not compromised. Always verify transaction details on the device screen."}, "severity": "warning"}], "factStatus": {"price": "unverified", "assets": "manufacturer_claim", "backup": "manufacturer_claim", "multisig": "manufacturer_claim", "warranty": "unverified", "airGapped": "manufacturer_claim", "platforms": "manufacturer_claim", "openSource": "manufacturer_claim", "passphrase": "manufacturer_claim", "connectivity": "manufacturer_claim", "secureElement": "manufacturer_claim"}, "formFactor": "stick", "openSource": {"note": {"de": "Apps sind Open Source; das Secure-Element-Betriebssystem ist geschlossen.", "en": "Apps are open source; the secure-element OS is closed."}, "firmware": "partial", "hardware": "no"}, "passphrase": true, "bitcoinOnly": false, "officialUrl": "https://www.ledger.com/", "releaseYear": 2019, "assetBreadth": 5, "connectivity": ["usb", "bluetooth"], "discontinued": false, "assetsSummary": {"de": "Tausende Coins und Token über Ledger Wallet und Drittanbieter-Wallets.", "en": "Thousands of coins and tokens via Ledger Wallet and third-party wallets."}, "companionApps": "Ledger Wallet; third-party wallets", "secureElement": {"chip": "ST33J2M0", "present": true, "certification": "CC EAL5+ (chip)"}, "priceCheckedAt": "2026-10-13", "scoreRationale": {"de": "Bewährt und mobil, aber im Vergleich zu neueren Modellen in die Jahre gekommen.", "en": "Proven and mobile-friendly but showing its age against newer models."}, "usabilityNotes": {"de": "", "en": ""}, "btcOnlyFirmware": false, "securityArchitecture": {"de": "G