nnect Kit supply-chain attack"}, "summary": {"de": "Eine kompromittierte Version der JavaScript-Bibliothek Connect Kit wurde veröffentlicht und genutzt, um Nutzer betroffener Web-Apps zu bestehlen. Die Geräte selbst waren nicht kompromittiert. Prüfen Sie Transaktionsdetails stets auf dem Gerätedisplay.", "en": "A compromised version of Ledger''s Connect Kit JavaScript library was published and used to drain users of affected third-party web apps. The hardware devices themselves were not compromised. Always verify transaction details on the device screen."}, "severity": "warning"}], "factStatus": {"price": "unverified", "assets": "manufacturer_claim", "backup": "manufacturer_claim", "multisig": "manufacturer_claim", "warranty": "unverified", "airGapped": "manufacturer_claim", "platforms": "manufacturer_claim", "openSource": "manufacturer_claim", "passphrase": "manufacturer_claim", "connectivity": "manufacturer_claim", "secureElement": "manufacturer_claim"}, "formFactor": "touch", "openSource": {"note": {"de": "Apps sind Open Source; das Secure-Element-Betriebssystem ist geschlossen.", "en": "Apps are open source; the secure-element OS is closed."}, "firmware": "partial", "hardware": "no"}, "passphrase": true, "bitcoinOnly": false, "officialUrl": "https://www.ledger.com/", "releaseYear": 2024, "assetBreadth": 5, "connectivity": ["usb", "bluetooth", "nfc"], "discontinued": false, "assetsSummary": {"de": "Tausende Coins und Token über Ledger Wallet und Drittanbieter-Wallets.", "en": "Thousands of coins and tokens via Ledger Wallet and third-party wallets."}, "companionApps": "Ledger Wallet; third-party wallets", "secureElement": {"chip": "Ledger secure element", "present": true, "certification": "CC EAL6+ (as reported)"}, "priceCheckedAt": "2026-10-13", "scoreRationale": {"de": "Tolles Display und viele Funktionen; Transparenz ist der Kompromiss.", "en": "Great screen and features; transparency is the trade-off."}, "usabilityNotes": {"de": "", "en": ""}, "btcOnlyFirmware": false, "securityArchitecture": {"de": "Secure-Element-Design mit großem E-Ink-Touchscreen, auf dem sich Adressen und Transaktionsdetails vor dem Signieren gut lesen lassen.", "en": "Secure-element design with a large E Ink touchscreen that makes it easier to read full addresses and transaction details before signing."}}', NULL, '2026-10-13 21:58:13.910322+00', '2026-10-13 22:19:58.807313+00');
INSERT INTO public.products VALUES ('ledger-stax', 'ledger', 'Ledger Stax', 'review', '{"cons": {"de": ["Teuer", "Geschlossenes Betriebssystem", "Kein Sicherheitsvorteil gegenüber der günstigeren Flex"], "en": ["Expensive", "Closed-source OS", "No security advantage over the cheaper Flex"]}, "pros": {"de": ["Größtes, gut lesbares Display", "Kabelloses Laden", "Hochwertiges Design"], "en": ["Largest, most readable screen", "Wireless charging", "Premium design"]}, "image": null, "input": "Touchscreen", "backup": ["bip39", "cloud_optional"], "prices": {"EUR": null, "GBP": null, "USD": 399}, "scores": {"value": 5, "backup": 7, "privacy": 5, "features": 9, "security": 7.5, "usability": 8.5}, "avoidIf": {"de": "Ihnen Preis-Leistung wichtig ist – die Flex bietet dieselbe Sicherheit günstiger.", "en": "Value for money matters — the Flex offers the same security for less."}, "battery": true, "bestFor": {"de": "Nutzer, denen Design und Displaygröße wichtig sind und die Ledgers Modell akzeptieren.", "en": "Users who prioritise design and screen size and are happy with Ledger''s model."}, "display": "3.7-inch curved E Ink touchscreen", "sources": [{"url": "https://www.ledger.com/", "label": "Ledger — official site"}], "tagline": {"de": "Ledgers Premium-Gerät mit gebogenem E-Ink-Display und kabellosem Laden", "en": "Ledger''s premium curved E Ink device with wireless charging"}, "editions": [], "multisig": "basic", "shipping": {"DE": {"de": "Noch nicht geprüft – Lieferzeit und Einfuhrabgaben im Checkout prüfen.", "en": "Not yet verified — check delivery times and import charges at checkout."}, "GB": {"de": "Noch nicht geprüft – Lieferzeit, MwSt. und Einfuhrabgaben im Checkout prüfen.", "en": "Not yet verified — check delivery times, VAT and import charges at checkout."}}, "warranty": {"de": "Herstellergarantie noch nicht geprüft. Beim Kauf von einem Händler in der EU bzw. UK gelten die gesetzlichen Gewährleistungsrechte.", "en": "Manufacturer warranty terms not yet verified. Statutory consumer rights apply when buying from a UK or EU seller."}, "airGapped": "no", "platforms": ["windows", "macos", "linux", "android", "ios"], "priceNote": {"de": "Unverbindliche Preisempfehlung laut Drittquellen zum angegebenen Datum; die Quellen widersprachen sich teils. Bitte im offiziellen Shop prüfen.", "en": "Recommended retail price as listed by third-party sources on the date shown; sources disagreed. Confirm at the official store."}, "advisories": [{"url": "", "date": "2020-07-14", "title": {"de": "Datenleck der Kundendatenbank (Onlineshop)", "en": "Customer database breach (e-commerce)"}, "summary": {"de": "Ledger meldete, dass Kontaktdaten aus der Shop- und Marketing-Datenbank abgeflossen sind. Gerätschlüssel waren nicht betroffen, doch Betroffene wurden mit Phishing und Drohungen angeschrieben. Seien Sie bei Nachrichten im Namen von Ledger misstrauisch.", "en": "Ledger disclosed that customer contact data from its e-commerce and marketing database was exposed. Device keys were not affected, but affected customers were targeted by phishing and threats. Be suspicious of any message claiming to be from Ledger."}, "severity": "warning"}, {"url": "", "date": "2023-05-16", "title": {"de": "Ankündigung von Ledger Recover", "en": "Ledger Recover announcement"}, "summary": {"de": "Ledger kündigte Recover an, einen optionalen kostenpflichtigen Dienst, der verschlüsselte Teile des Seeds bei Dritten sichert. Er ist freiwillig, zeigte aber, dass die geschlossene Firmware Schlüsselmaterial mit Zustimmung exportieren kann – was eine Debatte über Vertrauen in Closed-Source-Firmware auslöste.", "en": "Ledger announced Recover, an optional paid service that backs up encrypted shares of the seed with third parties. It is opt-in, but it showed that the closed firmware can export key material when the user consents, which prompted debate about trust in closed-source firmware."}, "severity": "info"}, {"url": "", "date": "2023-12-14", "title": {"de": "Supply-Chain-Angriff auf Ledger Connect Kit", "en": "Ledger Connect Kit supply-chain attack"}, "summary": {"de": "Eine kompromittierte Version der JavaScript-Bibliothek Connect Kit wurde veröffentlicht und genutzt, um Nutzer betroffener Web-Apps zu bestehlen. Die Geräte selbst waren nicht kompromittiert. Prüfen Sie Transaktionsdetails stets auf dem Gerätedisplay.", "en": "A compromised version of Ledger''s Connect Kit JavaScript library was published and used to drain users of affected third-party web apps. The hardware devices themselves were not compromised. Always verify transaction details on the device screen."}, "severity": "warning"}], "factStatus": {"price": "unverified", "assets": "manufacturer_claim", "backup": "manufacturer_claim", "multisig": "manufacturer_claim", "warranty": "unverified", "airGapped": "manufacturer_claim", "platforms": "manufacturer_claim", "openSource": "manufacturer_claim", "passphrase": "manufacturer_claim", "connectivity": "manufacturer_claim", "secureElement": "manufacturer_claim"}, "formFactor": "phone", "openSource": {"note": {"de": "Apps sind Open Source; das Secure-Element-Betriebssystem ist geschlossen.", "en": "Apps are open source; the secure-element OS is closed."}, "firmware": "partial", "hardware": "no"}, "passphrase": true, "bitcoinOnly": false, "officialUrl": "https://www.ledger.com/", "releaseYear": 2024, "assetBreadth": 5, "connectivity": ["usb", "bluetooth", "nfc"], "discontinued": false, "assetsSummary": {"de": "Tausende Coins und Token über Ledger Wallet und Drittanbieter-Wallets.", "en": "Thousands of coins and tokens via Ledger Wallet and third-party wallets."}, "companionApps": "Ledger Wallet; third-party wallets", "secureElement": {"chip": "Ledger secure element", "present": true, "certification": "CC EAL6+ (as reported)"}, "priceCheckedAt": "2026-10-13", "scoreRationale": {"de": "Sehr gute Bedienbarkeit; der Preis lässt sich sicherheitlich kaum begründen.", "en": "Excellent usability; price is hard to justify on security grounds."}, "usabilityNotes": {"de": "", "en": ""}, "btcOnlyFirmware": false, "securityArchitecture": {"de": "Gleiches Secure-Element-Modell wie die Flex mit dem größten Display der Reihe; der Aufpreis gilt Design und Komfort.", "en": "Same secure-element security model as the Flex with the largest screen in the range; design and convenience features are what you pay for."}}', NULL, '2026-10-13 21:58:13.912917+00', '2026-10-13 22:19:58.809501+00');
INSERT INTO public.products VALUES ('trezor-safe-3', 'trezor', 'Trezor Safe 3', 'review', '{"cons": {"de": ["Kein Bluetooth, kein Signieren am iPhone", "Kleines Display, Tastenbedienung", "Kein Air-Gapped-Signieren"], "en": ["No Bluetooth or iPhone signing", "Small screen, button navigation", "No air-gapped signing"]}, "pros": {"de": ["Günstig", "Firmware und Hardware Open Source", "Secure Element", "Multi-Share-Backup", "Bitcoin-only-Firmware optional"], "en": ["Low price", "Open-source firmware and hardware", "Secure element", "Multi-share backup", "Bitcoin-only firmware option"]}, "image": null, "input": "Two buttons", "backup": ["bip39", "slip39"], "prices": {"EUR": 79, "GBP": null, "USD": null}, "scores": {"value": 9, "backup": 9, "privacy": 8.5, "features": 7.5, "security": 8, "usability": 8}, "avoidIf": {"de": "Sie hauptsächlich ein iPhone nutzen oder air-gapped signieren möchten.", "en": "You mainly use an iPhone or want air-gapped signing."}, "battery": false, "bestFor": {"de": "Einsteiger mit kleinem Budget, die Open Source und ein Secure Element wollen.", "en": "Beginners on a budget who want open source and a secure element."}, "display": "Monochrome OLED", "sources": [{"url": "https://trezor.io/", "label": "Trezor — official site"}], "tagline": {"de": "Günstige Open-Source-Wallet mit Secure Element und Multi-Share-Backup", "en": "Affordable open-source wallet with a secure element and multi-share backup"}, "editions": ["Universal", "Bitcoin-only"], "multisig": "strong", "shipping": {"DE": {"de": "Noch nicht geprüft – Lieferzeit und Einfuhrabgaben im Checkout prüfen.", "en": "Not yet verified — check delivery times and import charges at checkout."}, "GB": {"de": "Noch nicht geprüft – Lieferzeit, MwSt. und Einfuhrabgaben im Checkout prüfen.", "en": "Not yet verified — check delivery times, VAT and import charges at checkout."}}, "warranty": {"de": "Herstellergarantie noch nicht geprüft. Beim Kauf von einem Händler in der EU bzw. UK gelten die gesetzlichen Gewährleistungsrechte.", "en": "Manufacturer warranty terms not yet verified. Statutory consumer rights apply when buying from a UK or EU seller."}, "airGapped": "no", "platforms": ["windows", "macos", "linux", "android"], "priceNote": {"de": "Unverbindliche Preisempfehlung laut Drittquellen zum angegebenen Datum; die Quellen widersprachen sich teils. Bitte im offiziellen Shop prüfen.", "en": "Recommended retail price as listed by third-party sources on the date shown; sources disagreed. Confirm at the official store."}, "advisories": [{"url": "", "date": "2025-03-01", "title": {"de": "Forscherbericht zu Glitching-Angriffen (Safe 3)", "en": "Researcher report on microcontroller glitching (Safe 3)"}, "summary": {"de": "Sicherheitsforscher berichteten, dass sich der Mikrocontroller der Safe 3 bei physischem Zugriff (z. B. in der Lieferkette) per Fehlerinjektion mit veränderter Firmware betreiben ließ. Laut Trezor bleibt der Seed durch Secure Element und PIN geschützt. Nur über offizielle Kanäle kaufen und die Echtheitsprüfung bei der Einrichtung beachten. Redaktion: Details vor Veröffentlichung anhand der Primärquellen prüfen.", "en": "Security researchers reported that the Safe 3''s general-purpose microcontroller could be fault-injected to run modified firmware given physical access, e.g. in a supply-chain scenario. Trezor stated that the seed remains protected by the secure element and PIN. Buy only from official channels and check the device''s authenticity during setup. Editor: verify details against primary sources before publishing."}, "severity": "info"}], "factStatus": {"price": "unverified", "assets": "manufacturer_claim", "backup": "manufacturer_claim", "multisig": "manufacturer_claim", "warranty": "unverified", "airGapped": "manufacturer_claim", "platforms": "manufacturer_claim", "openSource": "manufacturer_claim", "passphrase": "manufacturer_claim", "connectivity": "manufacturer_claim", "secureElement": "manufacturer_claim"}, "formFactor": "candybar", "openSource": {"note": {"de": "Firmware und Hardware sind Open Source; die Firmware des Secure Elements selbst nicht.", "en": "Firmware and hardware are open source; the secure element''s own firmware is not."}, "firmware": "yes", "hardware": "yes"}, "passphrase": true, "bitcoinOnly": false, "officialUrl": "https://trezor.io/", "releaseYear": 2023, "assetBreadth": 4, "connectivity": ["usb"], "discontinued": false, "assetsSummary": {"de": "Bitcoin und viele weitere Coins und Token über Trezor Suite und Drittanbieter; Bitcoin-only-Firmware verfügbar.", "en": "Bitcoin and a large number of other coins and tokens via Trezor Suite and third-party wallets; Bitcoin-only firmware available."}, "companionApps": "Trezor Suite; Sparrow, Electrum, MetaMask and others", "secureElement": {"chip": "Infineon OPTIGA Trust M", "present": true, "certification": "CC EAL6+ (chip)"}, "priceCheckedAt": "2026-10-13", "scoreRationale": {"de": "Hervorragendes Preis-Leistungs-Verhältnis mit Open Source und starken Backup-Optionen.", "en": "Outstanding value with open source and strong backup options."}, "usabilityNotes": {"de": "", "en": ""}, "btcOnlyFirmware": true, "securityArchitecture": {"de": "Die Open-Source-Firmware läuft auf dem Hauptprozessor; ein Secure Element schützt ein Geheimnis, das zusammen mit der PIN zum Entschlüsseln des Seeds nötig ist – Schutz gegen die physischen Angriffe, die ältere Trezor-Modelle betrafen. Multi-Share-Backups (SLIP-39) verteilen die Sicherung auf mehrere Orte.", "en": "Open-source firmware runs on the main microcontroller; a secure element protects a secret that, combined with the PIN, is required to decrypt the seed — adding resistance to the physical extraction attacks that affected older Trezor models. Supports multi-share backups (SLIP-39), which let you split a backup across several locations."}}', NULL, '2026-10-13 21:58:13.915849+00', '2026-10-13 22:19:58.811691+00');
