 "no", "platforms": ["windows", "macos", "linux", "android"], "priceNote": {"de": "Unverbindliche Preisempfehlung laut Drittquellen zum angegebenen Datum; die Quellen widersprachen sich teils. Bitte im offiziellen Shop prüfen.", "en": "Recommended retail price as listed by third-party sources on the date shown; sources disagreed. Confirm at the official store."}, "advisories": [], "factStatus": {"price": "unverified", "assets": "manufacturer_claim", "backup": "manufacturer_claim", "multisig": "manufacturer_claim", "warranty": "unverified", "airGapped": "manufacturer_claim", "platforms": "manufacturer_claim", "openSource": "manufacturer_claim", "passphrase": "manufacturer_claim", "connectivity": "manufacturer_claim", "secureElement": "manufacturer_claim"}, "formFactor": "touch", "openSource": {"note": {"de": "Firmware und Hardware sind Open Source; die Firmware des Secure Elements selbst nicht.", "en": "Firmware and hardware are open source; the secure element''s own firmware is not."}, "firmware": "yes", "hardware": "yes"}, "passphrase": true, "bitcoinOnly": false, "officialUrl": "https://trezor.io/", "releaseYear": 2024, "assetBreadth": 4, "connectivity": ["usb"], "discontinued": false, "assetsSummary": {"de": "Bitcoin und viele weitere Coins und Token; Bitcoin-only-Firmware verfügbar.", "en": "Bitcoin and many other coins and tokens; Bitcoin-only firmware available."}, "companionApps": "Trezor Suite; third-party wallets", "secureElement": {"chip": "Infineon OPTIGA Trust M", "present": true, "certification": "CC EAL6+ (chip)"}, "priceCheckedAt": "2026-10-13", "scoreRationale": {"de": "Open-Source-Sicherheit mit sehr guter Bedienbarkeit.", "en": "Open-source security with very good usability."}, "usabilityNotes": {"de": "", "en": ""}, "btcOnlyFirmware": true, "securityArchitecture": {"de": "Gleiches Sicherheitsmodell wie die Safe 3 (Open-Source-Firmware plus Secure Element) mit Farb-Touchscreen, der PIN- und Passphrase-Eingabe am Gerät erleichtert.", "en": "Same security model as the Safe 3 (open-source firmware plus secure element) with a colour touchscreen that makes PIN and passphrase entry on the device easier."}}', NULL, '2026-10-13 21:58:13.918854+00', '2026-10-13 22:19:58.813629+00');
INSERT INTO public.products VALUES ('trezor-safe-7', 'trezor', 'Trezor Safe 7', 'review', '{"cons": {"de": ["Teuer", "Neuer Chip mit wenig Praxiserfahrung", "Bluetooth als zusätzliche Funkschnittstelle"], "en": ["Expensive", "New chip with limited real-world track record", "Bluetooth adds a wireless interface"]}, "pros": {"de": ["Prüfbares Secure Element", "iPhone-Unterstützung per Bluetooth", "Open-Source-Firmware", "Multi-Share-Backup"], "en": ["Auditable secure element", "iPhone support via Bluetooth", "Open-source firmware", "Multi-share backup"]}, "image": null, "input": "Touchscreen", "backup": ["bip39", "slip39"], "prices": {"EUR": 249, "GBP": null, "USD": 249}, "scores": {"value": 6.5, "backup": 9, "privacy": 8.5, "features": 8.5, "security": 8, "usability": 8.5}, "avoidIf": {"de": "Sie bewährte Hardware oder ein Gerät ohne Funk bevorzugen.", "en": "You prefer proven hardware or a radio-free device."}, "battery": true, "bestFor": {"de": "Nutzer, die Open Source und iPhone-Unterstützung in einem Gerät suchen.", "en": "Users who want open source and iPhone support in one device."}, "display": "2.5-inch colour touchscreen (520×380), Gorilla Glass", "sources": [{"url": "https://trezor.io/", "label": "Trezor — official site"}], "tagline": {"de": "Trezors Flaggschiff mit Bluetooth und prüfbarem Secure Element TROPIC01", "en": "Trezor''s flagship with Bluetooth and the auditable TROPIC01 secure element"}, "editions": ["Universal", "Bitcoin-only"], "multisig": "strong", "shipping": {"DE": {"de": "Noch nicht geprüft – Lieferzeit und Einfuhrabgaben im Checkout prüfen.", "en": "Not yet verified — check delivery times and import charges at checkout."}, "GB": {"de": "Noch nicht geprüft – Lieferzeit, MwSt. und Einfuhrabgaben im Checkout prüfen.", "en": "Not yet verified — check delivery times, VAT and import charges at checkout."}}, "warranty": {"de": "Herstellergarantie noch nicht geprüft. Beim Kauf von einem Händler in der EU bzw. UK gelten die gesetzlichen Gewährleistungsrechte.", "en": "Manufacturer warranty terms not yet verified. Statutory consumer rights apply when buying from a UK or EU seller."}, "airGapped": "no", "platforms": ["windows", "macos", "linux", "android", "ios"], "priceNote": {"de": "Unverbindliche Preisempfehlung laut Drittquellen zum angegebenen Datum; die Quellen widersprachen sich teils. Bitte im offiziellen Shop prüfen.", "en": "Recommended retail price as listed by third-party sources on the date shown; sources disagreed. Confirm at the official store."}, "advisories": [], "factStatus": {"price": "unverified", "assets": "manufacturer_claim", "backup": "manufacturer_claim", "multisig": "manufacturer_claim", "warranty": "unverified", "airGapped": "manufacturer_claim", "platforms": "manufacturer_claim", "openSource": "manufacturer_claim", "passphrase": "manufacturer_claim", "connectivity": "manufacturer_claim", "secureElement": "manufacturer_claim"}, "formFactor": "touch", "openSource": {"note": {"de": "Firmware Open Source; TROPIC01 wird als offenes, prüfbares Secure Element vermarktet.", "en": "Firmware open source; TROPIC01 is marketed as an open, auditable secure element."}, "firmware": "yes", "hardware": "unknown"}, "passphrase": true, "bitcoinOnly": false, "officialUrl": "https://trezor.io/", "releaseYear": 2025, "assetBreadth": 4, "connectivity": ["usb", "bluetooth"], "discontinued": false, "assetsSummary": {"de": "Bitcoin und viele weitere Coins und Token; Bitcoin-only-Edition verfügbar.", "en": "Bitcoin and many other coins and tokens; Bitcoin-only edition available."}, "companionApps": "Trezor Suite; third-party wallets", "secureElement": {"chip": "TROPIC01 (auditable) + secondary EAL6+ secure element", "present": true, "certification": "Secondary chip EAL6+ (as reported)"}, "priceCheckedAt": "2026-10-13", "scoreRationale": {"de": "Vielversprechende Architektur mit offenem SE; die Sicherheitswertung bleibt vorerst konservativ.", "en": "Promising transparent-SE architecture; we hold the security score until it has a longer track record."}, "usabilityNotes": {"de": "", "en": ""}, "btcOnlyFirmware": true, "securityArchitecture": {"de": "Kombiniert Trezors Open-Source-Firmware mit zwei Secure Elements: dem offen dokumentierten TROPIC01 und einem zweiten EAL6+-Chip. Bluetooth-Sitzungen nutzen Trezors quelloffenes Host-Protokoll. Laut Launch-Unterlagen kommen Qi2-kompatibles kabelloses Laden und IP54 hinzu.", "en": "Combines Trezor''s open-source firmware with two secure elements: TROPIC01, whose design is published for audit, and a second EAL6+ chip. Bluetooth sessions use Trezor''s open-source host protocol. It also adds Qi2-compatible wireless charging and an IP54 rating, according to Trezor''s launch materials."}}', NULL, '2026-10-13 21:58:13.921309+00', '2026-10-13 22:19:58.815628+00');
INSERT INTO public.products VALUES ('coldcard-q', 'coinkite', 'COLDCARD Q', 'review', '{"cons": {"de": ["Gravierende Seed-Schwachstelle 2026 (in neuer Firmware behoben; alte Seeds müssen migriert werden)", "Hohe Einarbeitung", "Source-Available statt Open-Source-Lizenz", "Groß"], "en": ["Serious 2026 seed-generation flaw (fixed in new firmware; old seeds must be migrated)", "Steep learning curve", "Source-available rather than open-source licence", "Bulky"]}, "pros": {"de": ["Vollständig air-gapped", "Nur Bitcoin", "Sehr gute Multisig-Unterstützung", "Starke Profi-Funktionen"], "en": ["Fully air-gapped signing", "Bitcoin-only", "Excellent multisig support", "Powerful advanced features"]}, "image": null, "input": "QWERTY keyboard", "backup": ["bip39", "microsd", "seed_xor"], "prices": {"EUR": null, "GBP": null, "USD": 249}, "scores": {"value": 7, "backup": 8.5, "privacy": 8, "features": 9.5, "security": 6.5, "usability": 6}, "avoidIf": {"de": "Sie Einsteiger sind oder Firmware und Seed-Herkunft nicht sorgfältig prüfen möchten.", "en": "You are a beginner, or you are not prepared to verify firmware and seed provenance carefully."}, "battery": true, "bestFor": {"de": "Erfahrene Bitcoiner mit Air-Gap- oder Multisig-Setups, die Coinkites Migrationsanleitung befolgen.", "en": "Experienced Bitcoiners building air-gapped or multisig setups who will follow Coinkite''s migration guidance."}, "display": "Colour LCD", "sources": [{"url": "https://coldcard.com/security/status", "label": "COLDCARD — security status"}, {"url": "https://coldcard.com/security/migrate", "label": "COLDCARD — migrate an affected seed"}], "tagline": {"de": "Bitcoin-only-Signer, air-gapped, mit Tastatur und QR-Scanner", "en": "Bitcoin-only air-gapped signer with a full keyboard and QR scanner"}, "editions": [], "multisig": "strong", "shipping": {"DE": {"de": "Noch nicht geprüft – Lieferzeit und Einfuhrabgaben im Checkout prüfen.", "en": "Not yet verified — check delivery times and import charges at checkout."}, "GB": {"de": "Noch nicht geprüft – Lieferzeit, MwSt. und Einfuhrabgaben im Checkout prüfen.", "en": "Not yet verified — check delivery times, VAT and import charges at checkout."}}, "warranty": {"de": "Herstellergarantie noch nicht geprüft. Beim Kauf von einem Händler in der EU bzw. UK gelten die gesetzlichen Gewährleistungsrechte.", "en": "Manufacturer warranty terms not yet verified. Statutory consumer rights apply when buying from a UK or EU seller."}, "airGapped": "full", "platforms": ["windows", "macos", "linux", "android", "ios"], "priceNote": {"de": "Unverbindliche Preisempfehlung laut Drittquellen zum angegebenen Datum; die Quellen widersprachen sich teils. Bitte im offiziellen Shop prüfen.", "en": "Recommended retail price as listed by third-party sources on the date shown; sources disagreed. Confirm at the official store."}, "advisories": [{"url": "https://coldcard.com/security/status", "date": "2026-07-31", "title": {"de": "Schwachstelle bei der Seed-Erzeugung (2026)", "en": "Seed-generation entropy flaw (2026)"}, "summary": {"de": "Coinkite meldete einen Firmware-Fehler, der die Zufallserzeugung von Seeds auf COLDCARD-Geräten schwächte; laut Coinkite haben betroffene Mk4-, Mk5- und Q-Seeds nur rund 72 statt 128 Bit Entropie. Betroffen sind Seeds, die vor den korrigierten Versionen erzeugt wurden (Mk4/Mk5 Standard 5.6.0+, Q 1.5.0Q+, EDGE 6.6.0X/6.6.0QX+); Drittquellen schreiben der Lücke hohe Verluste zu. Ein Firmware-Update repariert einen bestehenden Seed NICHT: Betroffene müssen auf korrigierter Firmware einen neuen Seed erzeugen und ihre Coins umziehen. Seeds mit mindestens 50 privaten Würfelwürfen bewertet Coinkite gesondert. Folgen Sie den offiziellen Status- und Migrationsseiten von Coinkite.", "en": "Coinkite disclosed that a firmware bug weakened random seed generation on COLDCARD devices; Coinkite''s advisory describes affected Mk4, Mk5 and Q seeds as having roughly 72 bits of entropy instead of 128. Seeds generated before the fixed releases (Mk4/Mk5 standard 5.6.0+, Q 1.5.0Q+, EDGE 6.6.0X/6.6.0QX+) are affected; third-party reports attribute large losses to the flaw. Updating firmware does NOT repair an existing seed: affected users must create a new seed on fixed firmware and move funds. Coinkite treats seeds created with at least 50 private dice rolls separately. Follow Coinkite''s official status and migration pages."}, "severity": "critical"}], "factStatus": {"price": "unverified", "assets": "manufacturer_claim", "backup": "manufacturer_claim", "multisig": "manufacturer_claim", "warranty": "unverified", "airGapped": "manufacturer_claim", "platforms": "manufacturer_claim", "openSource": "manufacturer_claim", "passphrase": "manufacturer_claim", "connectivity": "manufacturer_claim", "secureElement": "manufacturer_claim"}, "formFactor": "keyboard", "openSource": {"note": {"de": "Der Firmware-Quellcode ist unter einer Source-Available-Lizenz veröffentlicht.", "en": "Firmware source code is published under a source-available licence."}, "firmware": "partial", "hardware": "no"}, "passphrase": true, "bitcoinOnly": true, "officialUrl": "https://coldcard.com/", "releaseYear": 2024, "assetBreadth": 0, "connectivity": ["usb", "nfc", "qr", "microsd"], "discontinued": false, "assetsSummary": {"de": "Nur Bitcoin.", "en": "Bitcoin only."}, "companionApps": "Sparrow, Nunchuk, Electrum, Specter and other PSBT-capable wallets", "secureElement": {"chip": "Dual secure elements (two vendors)", "present": true, "certification": ""}, "priceCheckedAt": "2026-10-13", "scoreRationale": {"de": "Funktionsreiches, air-gapped Bitcoin-only-Design – deutlich abgewertet wegen der Schwachstelle bei der Schlüsselerzeugung 2026.", "en": "Feature-rich, air-gapped Bitcoin-only design, heavily penalised for the 2026 key-generation flaw."}, "usabilityNotes": {"de": "", "en": ""}, "btcOnlyFirmware": true, "securityArchitecture": {"de": "Für air-gapped PSBT-Signieren via microSD, QR oder NFC gebaut, mit zwei Secure Elements verschiedener Hersteller und vielen Profi-Funktionen (Duress-/Trick-PINs, Seed XOR). Im Juli 2026 meldete Coinkite eine Schwachstelle bei der Seed-Erzeugung, die vor der korrigierten Firmware erzeugte Seeds betrifft – siehe Hinweis unten. Das senkt unsere Sicherheitswertung deutlich, bis die Korrektur sich länger bewährt hat.", "en": "Designed for air-gapped PSBT signing via microSD, QR or NFC, with dual secure elements from two vendors and many advanced features (duress PINs, trick PINs, Seed XOR). In July 2026 Coinkite disclosed a seed-generation entropy flaw affecting seeds created before fixed firmware — see the advisory below. This materially lowers our security score until the fix has a longer track record."}}', NULL, '2026-10-13 21:58:13.924313+00', '2026-10-13 22:19:58.817486+00');
