 "candybar", "openSource": {"note": {"de": "Firmware-Quellcode einsehbar (Source-Available).", "en": "Source-available firmware."}, "firmware": "partial", "hardware": "no"}, "passphrase": true, "bitcoinOnly": true, "officialUrl": "https://coldcard.com/", "releaseYear": 2022, "assetBreadth": 0, "connectivity": ["usb", "nfc", "microsd"], "discontinued": false, "assetsSummary": {"de": "Nur Bitcoin.", "en": "Bitcoin only."}, "companionApps": "Sparrow, Nunchuk, Electrum and other PSBT wallets", "secureElement": {"chip": "Dual secure elements", "present": true, "certification": ""}, "priceCheckedAt": "2026-10-13", "scoreRationale": {"de": "Entwurf – Verfügbarkeit ggü. Mk5 vor Veröffentlichung prüfen.", "en": "Draft — confirm current availability vs Mk5 before publishing."}, "usabilityNotes": {"de": "", "en": ""}, "btcOnlyFirmware": true, "securityArchitecture": {"de": "Air-gapped Bitcoin-only-Signer. Von der Seed-Schwachstelle 2026 betroffen – siehe Hinweis.", "en": "Air-gapped Bitcoin-only signer. Affected by the 2026 seed-generation flaw — see advisory."}}', NULL, '2026-10-13 21:58:13.926782+00', '2026-10-13 22:19:58.819503+00');
INSERT INTO public.products VALUES ('blockstream-jade-plus', 'blockstream', 'Blockstream Jade Plus', 'review', '{"cons": {"de": ["Kein klassisches Secure Element", "Nur Bitcoin und Liquid", "Blind-Oracle-Modell ist ungewöhnlich und erklärungsbedürftig"], "en": ["No conventional secure element", "Bitcoin and Liquid only", "Blind-oracle model is unusual and requires understanding"]}, "pros": {"de": ["Open-Source-Firmware", "Air-Gap per Kamera", "PIN-Server selbst betreibbar", "Günstig", "Mobil und Desktop"], "en": ["Open-source firmware", "Camera-based air-gapped signing", "Self-hostable PIN server", "Affordable", "Mobile and desktop"]}, "image": null, "input": "Buttons / jog wheel", "backup": ["bip39", "seedqr"], "prices": {"EUR": null, "GBP": null, "USD": 149}, "scores": {"value": 8, "backup": 8, "privacy": 8.5, "features": 8.5, "security": 7, "usability": 7.5}, "avoidIf": {"de": "Sie Altcoins halten oder ausdrücklich ein Secure Element wollen.", "en": "You hold altcoins or specifically want a secure element."}, "battery": true, "bestFor": {"de": "Bitcoiner, die einen günstigen, quelloffenen Signer mit Air-Gap-Option suchen.", "en": "Bitcoiners who want an affordable, open-source, air-gap-capable signer."}, "display": "Colour LCD", "sources": [{"url": "https://blockstream.com/press-releases/2025-01-03-blockstream-launch-jade-plus/", "label": "Blockstream — Jade Plus launch (Jan 2025)"}, {"url": "https://blockstream.com/jade/jade-comparison/", "label": "Blockstream — Jade comparison"}], "tagline": {"de": "Open-Source-Signer für Bitcoin & Liquid mit QR-Kamera für Air-Gap", "en": "Open-source Bitcoin & Liquid signer with camera-based QR air-gap"}, "editions": [], "multisig": "strong", "shipping": {"DE": {"de": "Noch nicht geprüft – Lieferzeit und Einfuhrabgaben im Checkout prüfen.", "en": "Not yet verified — check delivery times and import charges at checkout."}, "GB": {"de": "Noch nicht geprüft – Lieferzeit, MwSt. und Einfuhrabgaben im Checkout prüfen.", "en": "Not yet verified — check delivery times, VAT and import charges at checkout."}}, "warranty": {"de": "Herstellergarantie noch nicht geprüft. Beim Kauf von einem Händler in der EU bzw. UK gelten die gesetzlichen Gewährleistungsrechte.", "en": "Manufacturer warranty terms not yet verified. Statutory consumer rights apply when buying from a UK or EU seller."}, "airGapped": "optional", "platforms": ["windows", "macos", "linux", "android", "ios"], "priceNote": {"de": "Unverbindliche Preisempfehlung laut Drittquellen zum angegebenen Datum; die Quellen widersprachen sich teils. Bitte im offiziellen Shop prüfen.", "en": "Recommended retail price as listed by third-party sources on the date shown; sources disagreed. Confirm at the official store."}, "advisories": [{"url": "", "date": "2025-11-01", "title": {"de": "Sicherheitsfix in Firmware 1.0.37 und Downgrade-Schutz in 1.0.38", "en": "Firmware security fix (1.0.37) and downgrade protection (1.0.38)"}, "summary": {"de": "Laut Drittberichten lieferte Blockstream einen Sicherheitsfix in Jade-Firmware 1.0.37 (November 2025) und Downgrade-Schutz in 1.0.38; eine Ausnutzung ist nicht bekannt. Auf 1.0.38 oder neuer aktualisieren. Redaktion: mit Blockstreams eigener Meldung abgleichen.", "en": "According to third-party reports, Blockstream shipped a security fix in Jade firmware 1.0.37 (November 2025) and added downgrade protection in 1.0.38, with no known exploitation in the wild. Update to 1.0.38 or later. Editor: confirm against Blockstream''s own notice."}, "severity": "warning"}], "factStatus": {"price": "unverified", "assets": "manufacturer_claim", "backup": "manufacturer_claim", "multisig": "manufacturer_claim", "warranty": "unverified", "airGapped": "manufacturer_claim", "platforms": "manufacturer_claim", "openSource": "manufacturer_claim", "passphrase": "manufacturer_claim", "connectivity": "manufacturer_claim", "secureElement": "manufacturer_claim"}, "formFactor": "candybar", "openSource": {"note": {"de": "Die Firmware ist Open Source.", "en": "Firmware is open source."}, "firmware": "yes", "hardware": "unknown"}, "passphrase": true, "bitcoinOnly": true, "officialUrl": "https://blockstream.com/jade/", "releaseYear": 2025, "assetBreadth": 1, "connectivity": ["usb", "bluetooth", "qr", "microsd"], "discontinued": false, "assetsSummary": {"de": "Nur Bitcoin und Assets im Liquid-Netzwerk.", "en": "Bitcoin and Liquid Network assets only."}, "companionApps": "Blockstream app (formerly Green); Sparrow, Nunchuk, Electrum, Specter", "secureElement": {"chip": "No secure element; ''virtual secure element'' via blind oracle (PIN server)", "present": false, "certification": ""}, "priceCheckedAt": "2026-10-13", "scoreRationale": {"de": "Sehr offen und flexibel; fehlendes SE und ein Sicherheitsfix 2025 dämpfen die Sicherheitswertung.", "en": "Excellent openness and flexibility; no SE and a 2025 security fix temper the security score."}, "usabilityNotes": {"de": "", "en": ""}, "btcOnlyFirmware": true, "securityArchitecture": {"de": "Statt eines Secure Elements schützt Jade den verschlüsselten Seed mit einem „Blind Oracle“: Zum Entsperren braucht es PIN plus ein Geheimnis eines PIN-Servers (von Blockstream oder selbst betrieben), der Ihre Schlüssel nie erfährt. Das vermeidet geschlossene SE-Firmware, unterscheidet sich aber vom Schutz eines Secure Elements gegen physische Angriffe. Per Kamera und QR vollständig air-gapped nutzbar, auch zustandslos mit SeedQR. Laut Drittberichten enthielt Firmware 1.0.37 (November 2025) einen Sicherheitsfix – Firmware aktuell halten.", "en": "Instead of a secure element, Jade protects the encrypted seed with a ''blind oracle'': unlocking requires the PIN plus a secret held by a PIN server (Blockstream''s or your own), which never learns your keys. This avoids closed secure-element firmware but differs from SE-based physical-attack resistance. Can be used fully air-gapped via its camera and QR codes; supports stateless use with SeedQR. Third-party reports state that a security fix shipped in firmware 1.0.37 (November 2025) — keep firmware current."}}', NULL, '2026-10-13 21:58:13.931111+00', '2026-10-13 22:19:58.821151+00');
