INSERT INTO public.products VALUES ('foundation-passport-prime', 'foundation', 'Foundation Passport Prime', 'review', '{"cons": {"de": ["Teuer", "Junge Plattform; Community berichtet über Anfangsprobleme", "Bluetooth standardmäßig aktiv (reiner Air-Gap-Modus in Diskussion)"], "en": ["Expensive", "Young platform; community reports of early rough edges", "Bluetooth enabled by default (air-gap-only mode under discussion)"]}, "pros": {"de": ["Großer, hochwertiger Touchscreen", "Bitcoin-Fokus", "Manipulationserkennung", "Air-Gap per Kamera möglich"], "en": ["Large, high-quality touchscreen", "Bitcoin-focused", "Tamper detection", "Air-gap via camera available"]}, "image": null, "input": "Touchscreen", "backup": ["bip39", "multi_card"], "prices": {"EUR": null, "GBP": null, "USD": 349}, "scores": {"value": 5.5, "backup": 8, "privacy": 8.5, "features": 8, "security": 8, "usability": 8}, "avoidIf": {"de": "Sie preissensibel sind oder lange Praxiserfahrung erwarten.", "en": "You are price-sensitive or want a long, proven track record."}, "battery": true, "bestFor": {"de": "Bitcoin-Halter, die ein hochwertiges, smartphone-ähnliches Gerät wünschen.", "en": "Bitcoin holders who want a premium, phone-like signing experience."}, "display": "3.5-inch touchscreen, Gorilla Glass 5", "sources": [{"url": "https://www.foundation.xyz", "label": "Foundation — official site"}, {"url": "https://foundation.xyz/wp-content/uploads/2025/10/Passport-Prime-Audit-Response-2025.pdf", "label": "Foundation — Passport Prime audit response 2025 (PDF)"}], "tagline": {"de": "Premium-Bitcoin-Gerät mit großem Touchscreen, Kamera und Manipulationserkennung", "en": "Premium Bitcoin device with a large touchscreen, camera and tamper detection"}, "editions": [], "multisig": "strong", "shipping": {"DE": {"de": "Noch nicht geprüft – Lieferzeit und Einfuhrabgaben im Checkout prüfen.", "en": "Not yet verified — check delivery times and import charges at checkout."}, "GB": {"de": "Noch nicht geprüft – Lieferzeit, M