INSERT INTO public.articles VALUES ('0c638e45-da42-472c-9ce2-a4de08226a1c', 'page', 'de', 'cookies', 'page-cookies', 'Cookie-Richtlinie', NULL, 'Welche Cookies ColdCompare nutzt und wie Sie Ihre Auswahl ändern.', NULL, 'Wir setzen so wenige Cookies wie möglich. Ihre Auswahl können Sie jederzeit über **Cookie-Einstellungen** im Footer ändern.
